<?php
declare(strict_types=1);

function salesQuoteTypeLabels():array{return ['lifesmart'=>'LifeSmart','control4'=>'Control4','shelly'=>'Shelly','general'=>'General'];}
function salesQuoteStatusLabels():array{return ['borrador'=>'Borrador','enviado'=>'Enviado','visto'=>'Visto','aprobado'=>'Aprobado','rechazado'=>'Rechazado','vencido'=>'Vencido'];}

function salesQuotePublic(PDO $db,array $cfg,string $token):never{
 $s=$db->prepare('SELECT sq.*,c.business_name,c.cuit,p.project_number,p.name project_name,pl.name price_list_name,t.name template_name,t.intro_pdf_path,t.final_pdf_path FROM sales_quotes sq JOIN clients c ON c.id=sq.client_id LEFT JOIN projects p ON p.id=sq.project_id JOIN price_lists pl ON pl.id=sq.price_list_id JOIN sales_quote_templates t ON t.proposal_type=sq.proposal_type WHERE sq.public_token=?');$s->execute([$token]);$quote=$s->fetch();if(!$quote){http_response_code(404);exit('Presupuesto inexistente.');}
 if($quote['status']==='enviado')$db->prepare("UPDATE sales_quotes SET status='visto' WHERE id=? AND status='enviado'")->execute([$quote['id']]);
 $s=$db->prepare('SELECT * FROM sales_quote_items WHERE sales_quote_id=? ORDER BY sort_order,id');$s->execute([$quote['id']]);$items=$s->fetchAll();$types=salesQuoteTypeLabels();$tax=['sin_iva'=>'Sin IVA','iva_incluido'=>'IVA incluido','mas_iva'=>'Más IVA'];
 ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($quote['quote_number'])?> · Punto Domótica</title><style>:root{--o:#ff5708;--ink:#171717;--muted:#6d737b;--line:#ddd}*{box-sizing:border-box}body{margin:0;background:#161616;font:15px/1.45 Arial,sans-serif;color:var(--ink)}.toolbar{position:sticky;z-index:5;top:0;padding:12px;text-align:center;background:#111;color:#fff}.toolbar button,.toolbar a{display:inline-block;margin:3px;padding:9px 14px;border:0;border-radius:7px;background:var(--o);color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.pdf{display:block;width:min(100%,900px);height:92vh;margin:22px auto;border:0;background:#fff}.sheet{width:min(100% - 24px,900px);min-height:1120px;margin:22px auto;padding:58px;background:#fff}.head{display:flex;justify-content:space-between;gap:30px;padding-bottom:25px;border-bottom:5px solid var(--o)}.brand{font-size:26px;font-weight:800}.brand span{color:var(--o)}h1{font-size:34px;margin:32px 0 4px}.meta{color:var(--muted)}.client{margin:30px 0;padding:20px;background:#f4f4f4;border-left:5px solid var(--o)}table{width:100%;border-collapse:collapse;margin-top:26px}th{background:#171717;color:#fff;text-transform:uppercase;font-size:11px}th,td{padding:12px 9px;border-bottom:1px solid var(--line);text-align:left}.right{text-align:right}.totals{width:360px;margin:28px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:8px}.totals .grand{background:var(--o);color:#fff;font-size:19px;font-weight:bold}.notes{margin-top:35px;padding-top:20px;border-top:1px solid var(--line)}@media print{body{background:#fff}.toolbar,.pdf{display:none}.sheet{width:100%;margin:0;min-height:auto;box-shadow:none}.sheet+.sheet{page-break-before:always}}@media(max-width:650px){.sheet{padding:28px 18px}.head{display:block}.pdf{height:75vh}.hide-mobile{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir propuesta económica</button><?php if($quote['intro_pdf_path']):?><a href="<?=e($quote['intro_pdf_path'])?>" target="_blank">Abrir presentación</a><?php endif;?><?php if($quote['final_pdf_path']):?><a href="<?=e($quote['final_pdf_path'])?>" target="_blank">Abrir condiciones</a><?php endif;?></div><?php if($quote['intro_pdf_path']):?><iframe class="pdf" src="<?=e($quote['intro_pdf_path'])?>#view=FitH" title="Presentación <?=e($types[$quote['proposal_type']]??'')?>"></iframe><?php endif;?><section class="sheet"><div class="head"><div class="brand"><span>●</span> Punto Domótica</div><div><b><?=e($quote['quote_number'])?></b><br><?=e(date('d/m/Y',strtotime($quote['issue_date'])))?></div></div><h1>Propuesta económica</h1><p class="meta"><?=e($types[$quote['proposal_type']]??$quote['proposal_type'])?> · Lista <?=e($quote['price_list_name'])?> · <?=e($quote['currency'])?></p><div class="client"><b><?=e($quote['business_name'])?></b><?php if($quote['contact_name']):?><br>Atención: <?=e($quote['contact_name'])?><?php endif;?><?php if($quote['project_name']):?><br>Proyecto: <?=e($quote['project_number'])?> · <?=e($quote['project_name'])?><?php endif;?><?php if($quote['valid_until']):?><br>Válido hasta: <?=e(date('d/m/Y',strtotime($quote['valid_until'])))?><?php endif;?></div><table><thead><tr><th>Descripción</th><th class="right">Cantidad</th><th>Unidad</th><th class="right hide-mobile">Precio</th><th class="right">Total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?php if($item['sku']):?><small><?=e($item['sku'])?></small><br><?php endif;?><b><?=e($item['description'])?></b><?php if((float)$item['discount_percentage']):?><br><small>Descuento <?=e(number_format((float)$item['discount_percentage'],2,',','.'))?>%</small><?php endif;?></td><td class="right"><?=e(number_format((float)$item['quantity'],3,',','.'))?></td><td><?=e($item['unit'])?></td><td class="right hide-mobile"><?=mon($item['unit_price'],$quote['currency'])?></td><td class="right"><b><?=mon($item['line_total'],$quote['currency'])?></b></td></tr><?php endforeach;?></tbody></table><div class="totals"><div><span>Subtotal</span><b><?=mon($quote['subtotal'],$quote['currency'])?></b></div><?php if((float)$quote['discount_total']):?><div><span>Descuentos</span><b>- <?=mon($quote['discount_total'],$quote['currency'])?></b></div><?php endif;?><div><span><?=e($tax[$quote['tax_mode']]??$quote['tax_mode'])?><?php if($quote['tax_mode']==='mas_iva'):?> <?=e($quote['vat_rate'])?>%<?php endif;?></span><b><?=mon($quote['vat_total'],$quote['currency'])?></b></div><div class="grand"><span>Total</span><span><?=mon($quote['total'],$quote['currency'])?></span></div></div><?php if($quote['notes']):?><div class="notes"><b>Observaciones</b><p><?=nl2br(e($quote['notes']))?></p></div><?php endif;?></section><?php if($quote['final_pdf_path']):?><iframe class="pdf" src="<?=e($quote['final_pdf_path'])?>#view=FitH" title="Condiciones comerciales"></iframe><?php endif;?></body></html><?php exit;
}

function handleSalesQuotePost(string $a,PDO $db,array $cfg):bool{
 if(!in_array($a,['save_sales_quote','send_sales_quote_email'],true))return false;
 if($a==='send_sales_quote_email'){csrf();$id=(int)($_POST['sales_quote_id']??0);$s=$db->prepare('SELECT sq.*,c.business_name FROM sales_quotes sq JOIN clients c ON c.id=sq.client_id WHERE sq.id=?');$s->execute([$id]);$q=$s->fetch();if(!$q||!filter_var($q['contact_email'],FILTER_VALIDATE_EMAIL))throw new Exception('El presupuesto no tiene un email válido.');$url=rtrim($cfg['base_url'],'/').'/?a=public_sales_quote&token='.$q['public_token'];$subject='Presupuesto '.$q['quote_number'].' · Punto Domótica';$html='<p>Hola'.($q['contact_name']?', '.e($q['contact_name']):'').',</p><p>Te enviamos la propuesta <b>'.e($q['quote_number']).'</b> preparada por Punto Domótica.</p><p><a href="'.e($url).'">Ver propuesta completa</a></p>';$headers="MIME-Version: 1.0\r\nContent-type: text/html; charset=UTF-8\r\nFrom: ".($cfg['company_email']??'')."\r\n";if(!mail($q['contact_email'],$subject,$html,$headers))throw new Exception('El servidor no pudo enviar el email.');$db->beginTransaction();$db->prepare("UPDATE sales_quotes SET status=IF(status='borrador','enviado',status) WHERE id=?")->execute([$id]);$db->prepare("INSERT INTO sales_quote_sends(sales_quote_id,channel,recipient,sent_by) VALUES(?,'email',?,?)")->execute([$id,$q['contact_email'],$_SESSION['user']['id']]);$db->commit();msg('Presupuesto enviado por email.');go('?a=sales_quote&id='.$id);}
 csrf();$id=(int)($_POST['sales_quote_id']??0);$clientId=(int)($_POST['client_id']??0);$projectId=(int)($_POST['project_id']??0)?:null;$listId=(int)($_POST['price_list_id']??0);$type=$_POST['proposal_type']??'general';$currency=$_POST['currency']??'USD';$taxMode=$_POST['tax_mode']??'sin_iva';$vatRate=(float)($_POST['vat_rate']??21);if(!$clientId||!$listId||!isset(salesQuoteTypeLabels()[$type])||!in_array($currency,['ARS','USD'],true)||!in_array($taxMode,['sin_iva','iva_incluido','mas_iva'],true))throw new Exception('Revisá los datos principales del presupuesto.');if($projectId){$s=$db->prepare('SELECT COUNT(*) FROM projects WHERE id=? AND client_id=?');$s->execute([$projectId,$clientId]);if(!(int)$s->fetchColumn())throw new Exception('El proyecto no pertenece al cliente seleccionado.');}
 $items=[];$subtotal=0.0;$discountTotal=0.0;foreach($_POST['items']??[] as $i=>$row){$description=trim($row['description']??'');$qty=(float)($row['quantity']??0);$price=(float)($row['unit_price']??0);$discount=(float)($row['discount_percentage']??0);if($description===''||$qty<=0||$discount<0||$discount>100)continue;$gross=$qty*$price;$line=round($gross*(1-$discount/100),2);$subtotal+=$gross;$discountTotal+=$gross-$line;$items[]=['product_id'=>(int)($row['product_id']??0)?:null,'category_id'=>(int)($row['category_id']??0)?:null,'sku'=>trim($row['sku']??''),'description'=>$description,'quantity'=>$qty,'unit'=>trim($row['unit']??'Unidad')?:'Unidad','unit_price'=>$price,'discount_percentage'=>$discount,'line_total'=>$line];}if(!$items)throw new Exception('Agregá al menos un producto o concepto.');$net=$subtotal-$discountTotal;$vat=$taxMode==='mas_iva'?round($net*$vatRate/100,2):0.0;$total=$net+$vat;$contactEmail=strtolower(trim($_POST['contact_email']??''));if($contactEmail!==''&&!filter_var($contactEmail,FILTER_VALIDATE_EMAIL))throw new Exception('El email del contacto no es válido.');
 $db->beginTransaction();if(!$id){$year=date('Y',strtotime($_POST['issue_date']));$s=$db->prepare('SELECT COALESCE(MAX(id),0)+1 FROM sales_quotes');$s->execute();$number='PRE-'.$year.'-'.str_pad((string)$s->fetchColumn(),6,'0',STR_PAD_LEFT);$token=bin2hex(random_bytes(24));$db->prepare('INSERT INTO sales_quotes(quote_number,client_id,project_id,price_list_id,proposal_type,contact_name,contact_email,contact_whatsapp,issue_date,valid_until,currency,tax_mode,vat_rate,subtotal,discount_total,vat_total,total,status,public_token,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$number,$clientId,$projectId,$listId,$type,trim($_POST['contact_name']??''),$contactEmail,trim($_POST['contact_whatsapp']??''),$_POST['issue_date'],$_POST['valid_until']?:null,$_POST['currency'],$taxMode,$vatRate,$subtotal,$discountTotal,$vat,$total,'borrador',$token,trim($_POST['notes']??''),$_SESSION['user']['id']]);$id=(int)$db->lastInsertId();}else{$db->prepare('UPDATE sales_quotes SET client_id=?,project_id=?,price_list_id=?,proposal_type=?,contact_name=?,contact_email=?,contact_whatsapp=?,issue_date=?,valid_until=?,currency=?,tax_mode=?,vat_rate=?,subtotal=?,discount_total=?,vat_total=?,total=?,notes=? WHERE id=?')->execute([$clientId,$projectId,$listId,$type,trim($_POST['contact_name']??''),$contactEmail,trim($_POST['contact_whatsapp']??''),$_POST['issue_date'],$_POST['valid_until']?:null,$_POST['currency'],$taxMode,$vatRate,$subtotal,$discountTotal,$vat,$total,trim($_POST['notes']??''),$id]);$db->prepare('DELETE FROM sales_quote_items WHERE sales_quote_id=?')->execute([$id]);}
 $insert=$db->prepare('INSERT INTO sales_quote_items(sales_quote_id,product_id,category_id,sort_order,sku,description,quantity,unit,unit_price,discount_percentage,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?)');foreach($items as $order=>$item)$insert->execute([$id,$item['product_id'],$item['category_id'],$order,$item['sku'],$item['description'],$item['quantity'],$item['unit'],$item['unit_price'],$item['discount_percentage'],$item['line_total']]);$db->commit();msg('Presupuesto guardado.');go('?a=sales_quote&id='.$id);
}

function renderSalesQuoteRoute(string $a,PDO $db):bool{
 if($a==='sales_quotes'){$statuses=salesQuoteStatusLabels();$rows=$db->query('SELECT sq.*,c.business_name,p.project_number,p.name project_name,pl.name price_list_name FROM sales_quotes sq JOIN clients c ON c.id=sq.client_id LEFT JOIN projects p ON p.id=sq.project_id JOIN price_lists pl ON pl.id=sq.price_list_id ORDER BY sq.issue_date DESC,sq.id DESC')->fetchAll();?><div class="actions"><div style="flex:1"><span class="muted">Ventas</span><h1>Presupuestos</h1><p class="muted">Propuestas comerciales basadas en las listas de precios.</p></div><?php if(canModule('sales_quotes',true)):?><a class="btn" href="?a=new_sales_quote">+ Presupuesto</a><?php endif;?></div><div class="card scroll"><table><tr><th>Número / fecha</th><th>Cliente</th><th>Proyecto</th><th>Tipo</th><th>Lista</th><th>Estado</th><th class="right">Total</th><th>Acciones</th></tr><?php foreach($rows as $q):?><tr><td><b><?=e($q['quote_number'])?></b><br><?=e(date('d/m/Y',strtotime($q['issue_date'])))?></td><td><?=e($q['business_name'])?></td><td><?=e($q['project_name']?($q['project_number'].' · '.$q['project_name']):'Sin proyecto')?></td><td><?=e(salesQuoteTypeLabels()[$q['proposal_type']]??$q['proposal_type'])?></td><td><?=e($q['price_list_name'])?></td><td><span class="pill"><?=e($statuses[$q['status']]??$q['status'])?></span></td><td class="right"><b><?=mon($q['total'],$q['currency'])?></b></td><td><a class="btn light" href="?a=sales_quote&id=<?=$q['id']?>">Abrir</a></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">Todavía no hay presupuestos comerciales.</p><?php endif;?></div><?php return true;}
 if(in_array($a,['new_sales_quote','edit_sales_quote'],true)){$id=(int)($_GET['id']??0);$quote=null;$existingItems=[];if($id){$s=$db->prepare('SELECT * FROM sales_quotes WHERE id=?');$s->execute([$id]);$quote=$s->fetch();$s=$db->prepare('SELECT * FROM sales_quote_items WHERE sales_quote_id=? ORDER BY sort_order,id');$s->execute([$id]);$existingItems=$s->fetchAll();}if(!$quote)$quote=['id'=>0,'client_id'=>'','project_id'=>'','price_list_id'=>'','proposal_type'=>'lifesmart','contact_name'=>'','contact_email'=>'','contact_whatsapp'=>'','issue_date'=>date('Y-m-d'),'valid_until'=>date('Y-m-d',strtotime('+15 days')),'currency'=>'USD','tax_mode'=>'sin_iva','vat_rate'=>21,'notes'=>''];$clients=$db->query('SELECT * FROM clients WHERE active=1 ORDER BY business_name')->fetchAll();$projects=$db->query('SELECT id,client_id,project_number,name FROM projects ORDER BY created_at DESC')->fetchAll();$lists=$db->query('SELECT * FROM price_lists WHERE active=1 ORDER BY name')->fetchAll();$categories=$db->query('SELECT * FROM product_categories WHERE active=1 ORDER BY name')->fetchAll();$products=$db->query('SELECT p.id,p.category_id,p.sku,p.name,p.unit,pp.price_list_id,pp.price,pp.currency FROM products p LEFT JOIN product_prices pp ON pp.product_id=p.id WHERE p.active=1 ORDER BY p.name,pp.price_list_id')->fetchAll();?><div class="actions"><h1 style="flex:1"><?=$id?'Editar':'Nuevo'?> presupuesto</h1><a class="btn light" href="?a=sales_quotes">Cancelar</a></div><form method="post" action="?a=save_sales_quote" id="quote-form"><?=token()?><input type="hidden" name="sales_quote_id" value="<?=$quote['id']?>"><div class="card"><h2>Datos principales</h2><div class="grid"><p class="c3"><label>Tipo de presentación</label><select name="proposal_type"><?php foreach(salesQuoteTypeLabels() as $key=>$label):?><option value="<?=$key?>" <?=$quote['proposal_type']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></p><p class="c5"><label>Cliente</label><select name="client_id" id="client" required><option value="">Seleccionar…</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" data-name="<?=e($c['contact_name'])?>" data-email="<?=e($c['email'])?>" data-whatsapp="<?=e($c['whatsapp'])?>" <?=$quote['client_id']==$c['id']?'selected':''?>><?=e($c['business_name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Proyecto</label><select name="project_id" id="project"><option value="">Sin asignar</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>" data-client="<?=$p['client_id']?>" <?=$quote['project_id']==$p['id']?'selected':''?>><?=e($p['project_number'].' · '.$p['name'])?></option><?php endforeach;?></select></p><p class="c4"><label>Lista de precios</label><select name="price_list_id" id="price-list" required><option value="">Seleccionar…</option><?php foreach($lists as $l):?><option value="<?=$l['id']?>" data-currency="<?=$l['currency']?>" <?=$quote['price_list_id']==$l['id']?'selected':''?>><?=e($l['name'])?></option><?php endforeach;?></select></p><p class="c2"><label>Moneda</label><select name="currency" id="currency"><option value="USD" <?=$quote['currency']==='USD'?'selected':''?>>USD</option><option value="ARS" <?=$quote['currency']==='ARS'?'selected':''?>>ARS</option></select></p><p class="c3"><label>Fecha</label><input type="date" name="issue_date" value="<?=e($quote['issue_date'])?>" required></p><p class="c3"><label>Válido hasta</label><input type="date" name="valid_until" value="<?=e($quote['valid_until'])?>"></p><p class="c4"><label>Contacto</label><input name="contact_name" id="contact-name" value="<?=e($quote['contact_name'])?>"></p><p class="c4"><label>Email</label><input type="email" name="contact_email" id="contact-email" value="<?=e($quote['contact_email'])?>"></p><p class="c4"><label>WhatsApp</label><input name="contact_whatsapp" id="contact-whatsapp" value="<?=e($quote['contact_whatsapp'])?>"></p></div></div><div class="card"><div class="actions"><div style="flex:1"><h2>Productos y conceptos</h2><p class="muted">El tipo de presentación no limita las categorías.</p></div><select id="category-filter" style="width:240px"><option value="">Todas las categorías</option><?php foreach($categories as $cat):?><option value="<?=$cat['id']?>"><?=e($cat['name'])?></option><?php endforeach;?></select><button type="button" class="btn light" onclick="addItem()">+ Agregar concepto</button></div><div class="scroll"><table id="items-table"><thead><tr><th style="min-width:260px">Producto</th><th>Descripción</th><th>Cantidad</th><th>Unidad</th><th>Precio</th><th>Desc. %</th><th></th></tr></thead><tbody></tbody></table></div></div><div class="card"><div class="grid"><p class="c4"><label>Tratamiento de IVA</label><select name="tax_mode"><option value="sin_iva" <?=$quote['tax_mode']==='sin_iva'?'selected':''?>>Sin IVA</option><option value="iva_incluido" <?=$quote['tax_mode']==='iva_incluido'?'selected':''?>>IVA incluido</option><option value="mas_iva" <?=$quote['tax_mode']==='mas_iva'?'selected':''?>>Más IVA</option></select></p><p class="c3"><label>Alícuota %</label><input type="number" min="0" max="100" step=".01" name="vat_rate" value="<?=e($quote['vat_rate'])?>"></p><p class="c12"><label>Observaciones</label><textarea name="notes"><?=e($quote['notes'])?></textarea></p></div><button class="btn">Guardar presupuesto</button></div></form><script>const catalog=<?=json_encode($products,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,existing=<?=json_encode($existingItems,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let rowIndex=0;const byProduct={};catalog.forEach(p=>{byProduct[p.id]??={id:p.id,category_id:p.category_id,sku:p.sku,name:p.name,unit:p.unit,prices:{}};if(p.price_list_id)byProduct[p.id].prices[p.price_list_id]={price:p.price,currency:p.currency}});function options(){const category=document.getElementById('category-filter').value;return '<option value="">Concepto manual</option>'+Object.values(byProduct).filter(p=>!category||String(p.category_id)===category).map(p=>'<option value="'+p.id+'">'+(p.sku?p.sku+' · ':'')+p.name+'</option>').join('')}function addItem(data={}){const i=rowIndex++,tr=document.createElement('tr');tr.innerHTML='<td><select name="items['+i+'][product_id]" onchange="pick(this,'+i+')">'+options()+'</select><input type="hidden" name="items['+i+'][category_id]"><input type="hidden" name="items['+i+'][sku]"></td><td><input name="items['+i+'][description]" required></td><td><input type="number" min=".001" step=".001" name="items['+i+'][quantity]" value="1" required></td><td><input name="items['+i+'][unit]" value="Unidad"></td><td><input type="number" step=".01" name="items['+i+'][unit_price]" value="0" required></td><td><input type="number" min="0" max="100" step=".01" name="items['+i+'][discount_percentage]" value="0"></td><td><button type="button" class="btn light" onclick="this.closest(\'tr\').remove()">Quitar</button></td>';document.querySelector('#items-table tbody').appendChild(tr);if(data.product_id){tr.querySelector('select').value=data.product_id;pick(tr.querySelector('select'),i,false)}for(const key of ['category_id','sku','description','quantity','unit','unit_price','discount_percentage'])if(data[key]!==undefined)tr.querySelector('[name="items['+i+']['+key+']"]').value=data[key]}function pick(select,i,usePrice=true){const p=byProduct[select.value],row=select.closest('tr');if(!p)return;if(usePrice){row.querySelector('[name="items['+i+'][description]"]').value=p.name;row.querySelector('[name="items['+i+'][unit]"]').value=p.unit;const price=p.prices[document.getElementById('price-list').value];row.querySelector('[name="items['+i+'][unit_price]"]').value=price?price.price:0}row.querySelector('[name="items['+i+'][category_id]"]').value=p.category_id||'';row.querySelector('[name="items['+i+'][sku]"]').value=p.sku||''}document.getElementById('client').addEventListener('change',function(){const o=this.selectedOptions[0];document.getElementById('contact-name').value=o.dataset.name||'';document.getElementById('contact-email').value=o.dataset.email||'';document.getElementById('contact-whatsapp').value=o.dataset.whatsapp||'';filterProjects()});function filterProjects(){const client=document.getElementById('client').value;[...document.getElementById('project').options].forEach(o=>{if(!o.value)return;o.hidden=!!client&&o.dataset.client!==client});}document.getElementById('price-list').addEventListener('change',function(){const o=this.selectedOptions[0];if(o?.dataset.currency)document.getElementById('currency').value=o.dataset.currency});document.getElementById('category-filter').addEventListener('change',()=>{document.querySelectorAll('#items-table tbody select').forEach(s=>{const value=s.value;s.innerHTML=options();s.value=value})});existing.length?existing.forEach(addItem):addItem();filterProjects();</script><?php return true;}
 if($a==='sales_quote'){$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT sq.*,c.business_name,p.project_number,p.name project_name,pl.name price_list_name FROM sales_quotes sq JOIN clients c ON c.id=sq.client_id LEFT JOIN projects p ON p.id=sq.project_id JOIN price_lists pl ON pl.id=sq.price_list_id WHERE sq.id=?');$s->execute([$id]);$q=$s->fetch();if(!$q){echo '<div class="card">Presupuesto inexistente.</div>';return true;}$url='?a=public_sales_quote&token='.e($q['public_token']);?><div class="actions"><div style="flex:1"><span class="muted">Presupuesto comercial</span><h1><?=e($q['quote_number'])?></h1><p><?=e($q['business_name'])?><?=e($q['project_name']?' · '.$q['project_number'].' · '.$q['project_name']:'')?></p></div><span class="pill"><?=e(salesQuoteStatusLabels()[$q['status']]??$q['status'])?></span><div class="kpi"><?=mon($q['total'],$q['currency'])?></div></div><div class="card actions"><a class="btn" target="_blank" href="<?=$url?>">Ver propuesta</a><?php if(canModule('sales_quotes',true)):?><a class="btn light" href="?a=edit_sales_quote&id=<?=$id?>">Editar</a><?php if($q['contact_email']):?><form method="post" action="?a=send_sales_quote_email"><?=token()?><input type="hidden" name="sales_quote_id" value="<?=$id?>"><button class="btn light">Enviar por email</button></form><?php endif;?><?php if($q['contact_whatsapp']):?><a class="btn light" target="_blank" href="?a=sales_quote_whatsapp&id=<?=$id?>">Enviar por WhatsApp</a><?php endif;?><?php endif;?><a class="btn light" href="?a=sales_quotes">Volver</a></div><div class="card"><h2>Resumen</h2><p><b>Tipo:</b> <?=e(salesQuoteTypeLabels()[$q['proposal_type']]??$q['proposal_type'])?><br><b>Lista:</b> <?=e($q['price_list_name'])?><br><b>Contacto:</b> <?=e($q['contact_name']?:'—')?> · <?=e($q['contact_email']?:'Sin email')?> · <?=e($q['contact_whatsapp']?:'Sin WhatsApp')?><br><b>Validez:</b> <?=e($q['valid_until']?date('d/m/Y',strtotime($q['valid_until'])):'Sin vencimiento')?></p></div><?php return true;}
